log.raw:
{
  "critique": [
    {
      "design": "r1A",
      "good": "The six equal monthly columns create a consistent comparison rhythm, and the figures and month headings remain intact. More of the monthly sequence is visible initially than in the other designs.",
      "problems": "Every region name wraps, and the long Europe label occupies four lines. The resulting tall rows make comparisons down a month less compact.",
      "cause": "The 95px region column leaves 74px for text. The 59px monthly columns are wide enough to preserve their contents but put the last 90px of the table beyond the viewport."
    },
    {
      "design": "r1B",
      "good": "The wider region column reduces the longest label to three lines and keeps Asia Pacific on one line. Equal monthly widths preserve the parallel structure and intact figures.",
      "problems": "North America and Latin America still wrap, while the viewport cuts into May. Readers must scroll to see the end of the monthly sequence.",
      "cause": "The 110px region column leaves 89px for text, improving the labels but increasing overflow to 105px. Each month still needs 59px to keep its longest figure intact."
    },
    {
      "design": "r1C",
      "good": "All labels and values fit on one line, producing compact rows and easy comparisons within the visible columns.",
      "problems": "The region column takes up much of the initial view, leaving only two complete months visible. Following a region across all six months requires substantial horizontal scrolling.",
      "cause": "The 216px region column accommodates the longest label on one line but pushes the 571px table 211px beyond the viewport."
    }
  ],
  "done": false,
  "designs": [
    {
      "name": "balanced",
      "widths": [125, 59, 59, 59, 59, 59, 59],
      "change": "Give region names a little more room than in r1B while keeping the months equal and intact. This tests whether more labels can stay on one line without the large scrolling cost of r1C."
    },
    {
      "name": "compact-labels",
      "widths": [80, 59, 59, 59, 59, 59, 59],
      "change": "Use the minimum width that preserves the longest individual region word. This tests a narrower, more scroll-efficient layout while accepting taller wrapped labels."
    },
    {
      "name": "wide-labels",
      "widths": [150, 59, 59, 59, 59, 59, 59],
      "change": "Explore an intermediate region width that may shorten the longest label further, while retaining substantially less overflow than the all-one-line design."
    }
  ]
}
